    (SELECT count(*) FROM t WHERE TRY(d <= 1000000000000000000000000000000000000)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d <= 1000000000000000000000000000000000000)) AS le_s, (SELECT count(*) FROM t WHERE TRY(d <= 1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS le_e,
    (SELECT count(*) FROM t WHERE TRY(d > 1000000000000000000000000000000000000)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d > 1000000000000000000000000000000000000)) AS gt_s, (SELECT count(*) FROM t WHERE TRY(d > 1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM t WHERE TRY(d >= 1000000000000000000000000000000000000)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d >= 1000000000000000000000000000000000000)) AS ge_s, (SELECT count(*) FROM t WHERE TRY(d >= 1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM t WHERE TRY(d = 1000000000000000000000000000000000000)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d = 1000000000000000000000000000000000000)) AS eq_s, (SELECT count(*) FROM t WHERE TRY(d = 1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM t WHERE TRY(d <> 1000000000000000000000000000000000000)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d <> 1000000000000000000000000000000000000)) AS ne_s, (SELECT count(*) FROM t WHERE TRY(d <> 1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 27 AS n, 'd' AS col, '-1000000000000000000000000000000000000' AS lit,
    (SELECT count(*) FROM t WHERE TRY(d < -1000000000000000000000000000000000000)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d < -1000000000000000000000000000000000000)) AS lt_s, (SELECT count(*) FROM t WHERE TRY(d < -1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM t WHERE TRY(d <= -1000000000000000000000000000000000000)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d <= -1000000000000000000000000000000000000)) AS le_s, (SELECT count(*) FROM t WHERE TRY(d <= -1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS le_e,
    (SELECT count(*) FROM t WHERE TRY(d > -1000000000000000000000000000000000000)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d > -1000000000000000000000000000000000000)) AS gt_s, (SELECT count(*) FROM t WHERE TRY(d > -1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM t WHERE TRY(d >= -1000000000000000000000000000000000000)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d >= -1000000000000000000000000000000000000)) AS ge_s, (SELECT count(*) FROM t WHERE TRY(d >= -1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM t WHERE TRY(d = -1000000000000000000000000000000000000)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d = -1000000000000000000000000000000000000)) AS eq_s, (SELECT count(*) FROM t WHERE TRY(d = -1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM t WHERE TRY(d <> -1000000000000000000000000000000000000)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM t WHERE TRY(d <> -1000000000000000000000000000000000000)) AS ne_s, (SELECT count(*) FROM t WHERE TRY(d <> -1000000000000000000000000000000000000) IS NULL AND d IS NOT NULL) AS ne_e
) AS q ORDER BY n
) TO 'compare_d.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
